create temporary view uplift_stats_${grass_region_without_quote} as
SELECT
    model_id,
    MAX(IF(control_order_cnt <= 0, 0, (1.0000 * treatment_order_cnt / 9 / control_order_cnt - 1))) AS order_uplift,
    MAX(IF(control_imp_cnt <= 0, 0, (1.0000 * treatment_imp_cnt / 9 / control_imp_cnt - 1))) AS imp_uplift,
    MAX(IF(control_gmv <= 0, 0, (1.0000 * treatment_gmv / 9 / control_gmv - 1))) AS gmv_uplift
FROM (
    SELECT
        shop_id,
        item_id,
        model_id,
        SUM(IF(exp_group_type = 'treatment', imp_cnt, 0)) AS treatment_imp_cnt,
        SUM(IF(exp_group_type = 'control', imp_cnt, 0)) AS control_imp_cnt,
        SUM(IF(exp_group_type = 'treatment', order_cnt, 0)) AS treatment_order_cnt,
        SUM(IF(exp_group_type = 'control', order_cnt, 0)) AS control_order_cnt,
        SUM(IF(exp_group_type = 'treatment', gmv, 0)) AS treatment_gmv,
        SUM(IF(exp_group_type = 'control', gmv, 0)) AS control_gmv
    FROM
        srdi_mart.dws_sr_data_warehouse_tc_pb_exp_reward_1d
    WHERE
        grass_region IN (${grass_region})
        AND local_date BETWEEN DATE_SUB(${local_date}, 6) AND ${local_date}
        AND model_id > 0
    GROUP BY shop_id, item_id, model_id
) AS inner_table
GROUP BY model_id;

--sql_divide_splitter--
create temporary view top_imp_models_${grass_region_without_quote} as
SELECT
    model_id as imp_model_id,
    imp_uplift,
    order_uplift,
    gmv_uplift
FROM uplift_stats_${grass_region_without_quote}
ORDER BY imp_uplift DESC
LIMIT 1;

--sql_divide_splitter--
create temporary view top_order_models_${grass_region_without_quote} as
SELECT
    model_id as order_model_id,
    imp_uplift,
    order_uplift,
    gmv_uplift
FROM uplift_stats_${grass_region_without_quote}
WHERE gmv_uplift != 0
ORDER BY order_uplift DESC
LIMIT 1;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_tc_pb_reward_topwinner_7d
 partition (grass_region = ${grass_region},local_date = ${local_date})
SELECT
    t1.imp_model_id,
    t1.imp_uplift,
    t2.order_model_id,
    t2.order_uplift,
    t2.gmv_uplift
FROM top_imp_models_${grass_region_without_quote} t1
CROSS JOIN top_order_models_${grass_region_without_quote} t2;
